(function(root){'use strict';
const blueprints=[{id:'trend',name:'追光金融港',strategy:'趋势跟随',icon:'◈',color:'#90bfea',description:'沿着近期价格方向建立试验；震荡时容易反复交易。',turnover:150},{id:'value',name:'星河价值街',strategy:'价值研究',icon:'◇',color:'#d6b785',description:'用估值假设寻找便宜资产；低估可能持续，模型也会判断失误。',turnover:60},{id:'defense',name:'月湾稳健园',strategy:'低波动配置',icon:'⬡',color:'#91d8c1',description:'控制波动暴露；并不保本，也可能错过强劲上涨。',turnover:40}];
const factors=[{id:'momentum',name:'动量木材',icon:'▤',label:'动量因子',description:'近期相对强弱的线索；震荡反转时可能失效。'},{id:'lowvol',name:'低波钢材',icon:'▥',label:'低波动因子',description:'降低价格波动暴露；不代表零损失。'},{id:'value',name:'价值玻璃',icon:'▧',label:'估值因子',description:'价格与基本面尺度比较；需防价值陷阱。'},{id:'volume',name:'量能铜线',icon:'⌁',label:'成交量因子',description:'量能确认线索；拥挤和噪声可能使其失效。'}];
function init(s){if(!s.city)s.city={version:1,cycle:0,blueprints:['trend'],materials:{momentum:2,lowvol:2,value:1,volume:1},districts:[],ledger:[],draws:[],drawn:{},pending:null};return s.city;}
function draw(s,pool){const c=init(s),key=pool+'-'+c.cycle;if(c.drawn[key])throw Error('本周期已领取，推进行情后再来');c.drawn[key]=true;let item;if(pool==='strategy'){const available=blueprints.filter(b=>!c.blueprints.includes(b.id));item=available[Math.floor(Game.rand(s.seed+c.cycle*31+782)*available.length)];if(item)c.blueprints.push(item.id);else{c.materials.lowvol++;item={name:'蓝图已齐全 · 补充低波钢材'};}}else if(pool==='factor'){const f=factors[Math.floor(Game.rand(s.seed+c.cycle*37+521)*4)];c.materials[f.id]+=2;item={name:f.name+' × 2'};}else throw Error('未知卡池');c.draws.push({cycle:c.cycle,pool,item:item.name});return item.name;}
function build(s,id,factorIds,budget){const c=init(s);if(!c.blueprints.includes(id)||c.districts.some(d=>d.id===id))throw Error('蓝图不可用或区域已建成');if(!Number.isInteger(budget)||budget<100||budget>5000)throw Error('预算须为100–5000整数游戏币');if(factorIds.length<1||factorIds.length>2||new Set(factorIds).size!==factorIds.length)throw Error('选择1–2种不同材料');for(const f of factorIds)if(!factors.some(x=>x.id===f)||!c.materials[f])throw Error('材料不足');for(const f of factorIds)c.materials[f]--;const district={id,factors:[...factorIds],budget,development:12,stability:100,last:null};c.districts.push(district);c.pending=null;return district;}
function refit(s,id,ids,budget){const c=init(s),d=c.districts.find(d=>d.id===id);if(!d)throw Error('区域不存在');if(!Number.isInteger(budget)||budget<100||budget>5000)throw Error('预算须为100–5000整数');if(ids.length<1||ids.length>2||new Set(ids).size!==ids.length)throw Error('选择1–2种不同材料');for(const f of ids)if(!factors.some(x=>x.id===f)||(c.materials[f]||0)+(d.factors.includes(f)?1:0)<1)throw Error('材料不足');for(const f of d.factors)c.materials[f]++;for(const f of ids)c.materials[f]--;d.factors=[...ids];d.budget=budget;c.pending=null;}
function market(seed,cycle){const x=Game.rand((seed+cycle*7919+95671)>>>0);return {seed:(seed+cycle*7919+95671)>>>0,regime:x<.34?'上行':x<.67?'震荡':'下行',basisPoints:Math.floor(x*1601)-800};}
function returns(d,m){let bp=d.id==='trend'?m.basisPoints:d.id==='value'?Math.round(m.basisPoints*.65)+80:Math.round(m.basisPoints*.35);if(d.factors.includes('momentum'))bp+=m.regime==='上行'?180:-100;if(d.factors.includes('lowvol'))bp=Math.round(bp*.65);if(d.factors.includes('value'))bp+=m.regime==='震荡'?120:-40;if(d.factors.includes('volume'))bp+=m.regime==='上行'?80:-60;const turnover=blueprints.find(b=>b.id===d.id).turnover+(d.factors.length-1)*50;return {bp,turnover,fee:Math.ceil(d.budget*turnover/10000),gross:Math.floor(d.budget*bp/10000)};}
function draft(s){const c=init(s);if(!c.districts.length)throw Error('先建设至少一个策略区域');const amount=c.districts.reduce((n,d)=>n+d.budget,0),fees=c.districts.reduce((n,d)=>n+returns(d,{basisPoints:0,regime:'震荡'}).fee,0);if(amount+fees>s.balance)throw Error('本轮总投入和维护费超过现金，请先下调区域预算');return {cycle:c.cycle,key:s.id+'-city-'+c.cycle,amount,fees,config:JSON.stringify(c.districts.map(d=>({id:d.id,factors:d.factors,budget:d.budget}))),rule:'city-1.0'};}
function settle(s,a){const c=init(s),prior=c.ledger.find(e=>e.idempotencyKey===a.key);if(prior)return prior;const valid=draft(s);if(a.key!==valid.key||a.config!==valid.config||a.cycle!==valid.cycle)throw Error('城市方案已变化，请重新确认');const m=market(s.seed,c.cycle),before=s.balance,details=c.districts.map(d=>{const r=returns(d,m),delta=r.gross-r.fee,credit=d.budget+r.gross;d.development=Math.max(0,Math.min(100,d.development+(delta>0?Math.max(1,Math.floor(delta/10)):0)));d.stability=Math.max(0,Math.min(100,d.stability+(delta<0?-Math.ceil(Math.abs(delta)/20):2)));d.last={...r,delta,credit,cycle:c.cycle};return {id:d.id,budget:d.budget,factors:[...d.factors],...d.last};}),delta=details.reduce((n,d)=>n+d.delta,0);s.balance+=delta;const entry={idempotencyKey:a.key,cycle:c.cycle,market:m,rule:a.rule,proposal:a,details,balanceBefore:before,balanceAfter:s.balance,delta};c.ledger.push(entry);c.cycle++;c.pending=null;Game.evidence(s,'city','周期'+c.cycle+'：'+details.map(d=>d.id+'预算'+d.budget+'，材料'+d.factors.join('/')).join('；'),'observed_action','during',false);return entry;}
const api={blueprints,factors,init,draw,build,refit,market,returns,draft,settle};if(typeof module!=='undefined')module.exports=api;else root.GameCity=api;
})(typeof window==='undefined'?globalThis:window);
